const BASE_URL = 'https://api.loe.lviv.ua';

const menus = $input.first().json;
const items = Array.isArray(menus) ? menus[0]?.menuItems : menus?.menuItems;

if (!items || items.length === 0) {
  throw new Error('No menu items found in API response');
}

// Today schedule (first item)
const today = items[0];
const rawHtml = today.rawHtml || '';
const imageUrl = today.imageUrl ? BASE_URL + today.imageUrl : '';
const mobileImageUrl = today.slug ? BASE_URL + today.slug : '';

// Tomorrow schedule (third item, index 2, if exists)
const tomorrow = items.length > 2 ? items[2] : null;
const tomorrowRawHtml = tomorrow?.rawHtml || '';
const tomorrowImageUrl = tomorrow?.imageUrl ? BASE_URL + tomorrow.imageUrl : '';
const tomorrowMobileImageUrl = tomorrow?.slug ? BASE_URL + tomorrow.slug : '';

return [{
  json: {
    rawHtml,
    imageUrl,
    mobileImageUrl,
    tomorrowRawHtml,
    tomorrowImageUrl,
    tomorrowMobileImageUrl
  }
}];
